with
expected_tables(name) as (select pg_catalog.unnest(array['private.audit_logs', 'private.certificate_counters', 'private.certificate_documents', 'private.certificate_render_secrets', 'private.command_receipts', 'private.maintenance_runs', 'private.outbox_jobs', 'private.queue_counters', 'private.record_counters', 'private.reminder_checks', 'private.settings', 'private.staff_account_creations', 'public.antigens', 'public.appointment_items', 'public.appointments', 'public.barangays', 'public.card_submissions', 'public.catchup_plan_items', 'public.catchup_plans', 'public.certificate_items', 'public.certificates', 'public.checkins', 'public.child_clinic_enrollments', 'public.child_programs', 'public.child_staff_notes', 'public.children', 'public.clinic_sessions', 'public.clinical_holds', 'public.clinics', 'public.cold_chain_limits', 'public.content_items', 'public.content_versions', 'public.dose_credits', 'public.encounters', 'public.followup_attempts', 'public.followup_snapshots', 'public.guardian_child_relationships', 'public.guardians', 'public.messages', 'public.ops_checks', 'public.organizations', 'public.paper_tallies', 'public.privacy_records', 'public.product_antigens', 'public.profiles', 'public.qr_passes', 'public.queue_entries', 'public.queue_events', 'public.record_attachments', 'public.record_review_cases', 'public.record_transfers', 'public.schedule_evaluations', 'public.schedule_fixtures', 'public.schedule_rule_dependencies', 'public.schedule_rules', 'public.schedule_versions', 'public.sms_consents', 'public.sms_events', 'public.sms_messages', 'public.staff_applications', 'public.staff_memberships', 'public.stock_balances', 'public.stock_locations', 'public.stock_movements', 'public.stock_transactions', 'public.stock_transfers', 'public.temperature_readings', 'public.temperature_reviews', 'public.vaccination_events', 'public.vaccination_revisions', 'public.vaccine_lots', 'public.vaccine_products']::text[])),
expected_versions(version) as (select pg_catalog.unnest(array['0000', '0001', '0002', '0003', '0004', '0005', '0006', '0007', '0008', '0009', '0010', '0011', '0012', '0013', '0014', '0015', '0016', '0017', '0018', '0019', '0020', '0021', '0022', '0023', '0024', '0025', '0026', '0027', '0028', '0029', '0030', '0031', '0032', '0033', '0034', '0035', '0036', '0037', '0038', '0039', '0040', '0041', '0042', '0043', '0044', '0045', '0046', '0047', '0048', '0049', '0050', '0051', '0052', '0053', '0054', '0055', '0056', '0057', '0058', '0059', '0060']::text[])),
public_rel as (
  select c.oid, c.relname, c.relkind, c.relrowsecurity from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'f')
    and not exists (select 1 from pg_catalog.pg_depend d where d.objid = c.oid and d.deptype = 'e')
),
private_rel as (
  select c.oid, c.relname from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'private' and c.relkind in ('r', 'p', 'v', 'm', 'f', 'S')
),
fn as (
  select p.oid, n.nspname, p.proname, p.prosecdef, p.proconfig, p.proacl, p.proowner,
         pg_catalog.format('%I.%I(%s)', n.nspname, p.proname, pg_catalog.pg_get_function_identity_arguments(p.oid)) as sig
  from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
  where n.nspname in ('public', 'private')
    and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')
),
allowed(names) as (select array['accept_record_transfer', 'accept_staff_application', 'acknowledge_clinic_privacy_notice', 'activate_schedule', 'add_child_note', 'answer_checkin', 'approve_correction', 'approve_record_transfer_release', 'approve_schedule', 'approve_staff_membership', 'approve_stock_adjustment', 'begin_certificate_render', 'book_appointment', 'call_next', 'cancel_appointment', 'cancel_catchup_plan', 'cancel_record_transfer_guardian', 'cancel_session', 'cancel_stock_transfer', 'check_in', 'close_service_day', 'close_stock_location', 'complete_staff_account_creation', 'confirm_child_identity', 'create_antigen', 'create_checkin', 'create_child_provisional', 'create_session', 'create_stock_location', 'create_vaccine_product', 'decline_record_transfer', 'discard_schedule_draft', 'evaluate_child', 'find_profile_for_grant', 'get_certificate_pdf', 'get_checkin_policy', 'get_clinic_profile', 'get_contact_preferences', 'get_my_context', 'get_open_encounter', 'get_ops_status', 'get_pending_privacy_notices', 'get_privacy_notice', 'get_schedule_version', 'guardian_care_content', 'guardian_child_history', 'guardian_child_notes', 'guardian_get_catchup_plan', 'guardian_get_schedule', 'guardian_list_card_submissions', 'guardian_list_certificates', 'guardian_list_sessions', 'guardian_queue_status', 'import_schedule_draft', 'initiate_record_transfer_out', 'issue_certificate', 'issue_qr_pass', 'list_active_products', 'list_appointments', 'list_catchup_plans', 'list_catchup_reviews', 'list_checkins', 'list_child_appointments', 'list_child_certificates', 'list_child_guardian_contacts', 'list_child_history', 'list_child_notes', 'list_clinical_holds', 'list_clinical_master', 'list_content', 'list_followup_worklist', 'list_lot_ledger', 'list_public_clinics', 'list_queue', 'list_record_transfers', 'list_review_cases', 'list_session_roster', 'list_sessions', 'list_staff_applications', 'list_staff_memberships', 'list_stock', 'list_stock_transfers', 'list_temperature', 'log_followup_attempt', 'mark_guardian_contact_invalid', 'mark_messages_read', 'merge_children', 'my_appointments', 'my_checkins', 'my_children', 'my_messages', 'my_record_transfers', 'my_staff_applications', 'place_clinical_hold', 'prepare_staff_account_creation', 'preview_schedule_impact', 'propose_stock_adjustment', 'public_queue_display', 'queue_transition', 'receive_stock', 'receive_stock_transfer', 'reconcile_stock', 'record_administration', 'record_administration_exception', 'record_ops_check', 'record_outside_dose_staff', 'record_paper_tally', 'record_temperature', 'record_wastage', 'refresh_followup', 'register_child_staff', 'register_lot', 'reject_correction', 'reject_staff_application', 'reject_stock_adjustment', 'release_clinical_hold', 'report_backlog', 'report_daily_activity', 'report_outside_dose', 'report_paper_reconciliation', 'report_stock_summary', 'report_vaccinations_by_product', 'request_child_edit', 'request_correction', 'request_guardian_link', 'request_record_transfer_guardian', 'request_staff_membership', 'reschedule_appointment', 'resolve_administration_exception', 'resolve_link_case', 'resolve_qr', 'resolve_review_case', 'resolve_transfer_shortfall', 'retire_content', 'retire_schedule', 'return_schedule_to_draft', 'review_card_submission', 'review_catchup_plan', 'review_content', 'review_temperature_excursion', 'revoke_certificate', 'revoke_qr_pass', 'revoke_staff_membership', 'save_catchup_draft', 'save_content_draft', 'search_audit', 'send_stock_transfer', 'service_day_backlog', 'set_catchup_item_status', 'set_checkin_policy', 'set_child_record_status', 'set_cold_chain_limits', 'set_contact_preferences', 'set_lot_disposition', 'set_master_status', 'set_privacy_notice', 'set_queue_priority', 'set_relationship_status', 'staff_get_child', 'staff_list_card_submissions', 'staff_search_children', 'store_certificate_pdf', 'submit_card_record', 'submit_catchup_plan', 'submit_content', 'submit_schedule_for_review', 'submit_staff_application', 'trace_lot_use', 'update_child_identity', 'update_clinic_profile', 'update_my_profile', 'update_session_capacity', 'update_staff_location', 'verify_certificate', 'verify_guardian_contact', 'verify_outside_dose', 'verify_relationship', 'withdraw_card_submission', 'withdraw_staff_application']::text[]),
history as (
  select version from supabase_migrations.schema_migrations
),
checks(ord, check_name, offenders, info) as (
  select 1, 'expected tables exist',
    (select pg_catalog.array_agg(name order by name) from expected_tables where pg_catalog.to_regclass(name) is null), null::text
  union all select 2, 'RLS enabled on every public table',
    (select pg_catalog.array_agg(relname order by relname) from public_rel where relkind in ('r', 'p') and not relrowsecurity), null
  union all select 3, 'anon: no table/view privilege beyond SELECT on the allowlist',
    (select pg_catalog.array_agg(relname order by relname) from public_rel
      where pg_catalog.has_table_privilege('anon', oid, 'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER')
         or pg_catalog.has_any_column_privilege('anon', oid, 'INSERT, UPDATE, REFERENCES')
         or (pg_catalog.has_table_privilege('anon', oid, 'SELECT') and relname <> all (array['barangays', 'public_clinics']::text[]))), null
  union all select 4, 'authenticated: no table-wide write privilege on public relations',
    (select pg_catalog.array_agg(relname order by relname) from public_rel
      where pg_catalog.has_table_privilege('authenticated', oid, 'INSERT, UPDATE, DELETE, TRUNCATE')), null
  union all select 5, 'authenticated: column UPDATE only on profiles(display_name, locale)',
    (select pg_catalog.array_agg(r.relname || '.' || a.attname order by r.relname, a.attname)
       from public_rel r join pg_catalog.pg_attribute a on a.attrelid = r.oid and a.attnum > 0 and not a.attisdropped
      where pg_catalog.has_column_privilege('authenticated', r.oid, a.attnum, 'INSERT, UPDATE')
        and not (r.relname = 'profiles' and a.attname in ('display_name', 'locale'))), null
  union all select 6, 'schema private: no USAGE for anon or PUBLIC',
    (select pg_catalog.array_agg(g order by g) from pg_catalog.unnest(array['anon', 'public']) g
      where pg_catalog.has_schema_privilege(g, 'private', 'USAGE')), null
  union all select 7, 'private relations: no privilege for anon/authenticated/service_role',
    (select pg_catalog.array_agg(distinct relname) from private_rel, pg_catalog.unnest(array['anon', 'authenticated', 'service_role']) g
      where pg_catalog.has_table_privilege(g, oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER')), null
  union all select 8, 'every SECURITY DEFINER function in public/private pins search_path to empty',
    (select pg_catalog.array_agg(sig order by sig) from fn
      where prosecdef and not ('search_path=""' = any (coalesce(proconfig, '{}'::text[])))), null
  union all select 9, 'anon: EXECUTE only on the public allowlist',
    (select pg_catalog.array_agg(sig order by sig) from fn
      where pg_catalog.has_function_privilege('anon', oid, 'EXECUTE')
        and not (nspname = 'public' and proname = any (array['list_public_clinics', 'public_queue_display', 'verify_certificate']::text[]))), null
  union all select 10, 'no function in public/private is executable by PUBLIC',
    (select pg_catalog.array_agg(sig order by sig) from fn
      where exists (select 1 from pg_catalog.aclexplode(coalesce(proacl, pg_catalog.acldefault('f', proowner))) a
                    where a.grantee = 0 and a.privilege_type = 'EXECUTE')), null
  union all select 11, 'authenticated: EXECUTE on private only for RLS helpers',
    (select pg_catalog.array_agg(sig order by sig) from fn
      where nspname = 'private' and pg_catalog.has_function_privilege('authenticated', oid, 'EXECUTE')
        and proname <> all (array['clinics_with', 'guardian_can_read_child', 'has_capability', 'my_guardian_ids', 'session_ok']::text[])), null
  union all select 12, 'runtime roles from 0028 exist, cannot log in or bypass RLS, hold their grants',
    (select pg_catalog.array_agg(problem order by problem) from (
       select e.role || ': missing or unsafe' as problem from (values ('cvsrs_outbox_worker', 'claim_sms'), ('cvsrs_outbox_worker', 'mark_sms'), ('cvsrs_outbox_worker', 'process_outbox'), ('cvsrs_sms_webhook', 'record_sms_event')) e(role, fn)
        left join pg_catalog.pg_roles r on r.rolname = e.role
        where r.oid is null or r.rolcanlogin or r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb
       union
       select e.role || ' lacks EXECUTE on private.' || e.fn
         from (values ('cvsrs_outbox_worker', 'claim_sms'), ('cvsrs_outbox_worker', 'mark_sms'), ('cvsrs_outbox_worker', 'process_outbox'), ('cvsrs_sms_webhook', 'record_sms_event')) e(role, fn)
        where exists (select 1 from pg_catalog.pg_roles where rolname = e.role)
          and not exists (select 1 from fn where fn.nspname = 'private' and fn.proname = e.fn
                          and pg_catalog.has_function_privilege(e.role, fn.oid, 'EXECUTE'))
     ) x), null
  union all select 13, 'runtime roles have no table privileges in public/private',
    (select pg_catalog.array_agg(distinct g || ' on ' || relname) from (select oid, relname from public_rel union all select oid, relname from private_rel) r,
       pg_catalog.unnest(array['cvsrs_outbox_worker', 'cvsrs_sms_webhook']::text[]) g
      where exists (select 1 from pg_catalog.pg_roles where rolname = g)
        and pg_catalog.has_table_privilege(g, r.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE')), null
  union all select 14, 'required extensions installed in schema extensions',
    (select pg_catalog.array_agg(x order by x) from pg_catalog.unnest(array['pg_trgm', 'pgcrypto', 'unaccent']::text[]) x
      where not exists (select 1 from pg_catalog.pg_extension e join pg_catalog.pg_namespace n on n.oid = e.extnamespace
                        where e.extname = x and n.nspname = 'extensions')), null
  union all select 15, 'profile trigger on auth.users present',
    (select array['on_auth_user_created'] where not exists (select 1 from pg_catalog.pg_trigger
      where tgname = 'on_auth_user_created' and tgrelid = 'auth.users'::regclass and not tgisinternal)), null
  union all select 16, 'deployment switches: demo_mode false, require_staff_mfa true',
    (select pg_catalog.array_agg(key || '=' || value::text order by key) from private.settings
      where (key = 'demo_mode' and value <> 'false'::jsonb) or (key = 'require_staff_mfa' and value <> 'true'::jsonb)), null
  union all select 17, 'migration history matches the migration files',
    (select pg_catalog.array_agg(problem order by problem) from (
       select 'missing ' || version as problem from expected_versions where version not in (select version from history)
       union all select 'unexpected ' || version from history where version not in (select version from expected_versions)
     ) x), null
  union all select 18, 'authenticated: public EXECUTE set equals the app RPC allowlist (src/lib/db/port.ts)',
    (select pg_catalog.array_agg(problem order by problem) from (
       select distinct 'not in app allowlist: ' || proname as problem from fn
        where nspname = 'public' and pg_catalog.has_function_privilege('authenticated', oid, 'EXECUTE') and proname <> all (allowed.names)
       union all
       select 'not executable: ' || a from pg_catalog.unnest(allowed.names) a
        where not exists (select 1 from fn where nspname = 'public' and proname = a and pg_catalog.has_function_privilege('authenticated', oid, 'EXECUTE'))
     ) x), null
  from allowed
  union all select 19, 'certificate render secret provisioned (operator step, see README)', null,
    case when exists (select 1 from private.certificate_render_secrets) then 'provisioned'
         else 'not yet provisioned: certificate issuance fails closed until it is' end
  union all select 20, 'organizations and staff grants (operator step)', null,
    (select pg_catalog.format('%s organization(s), %s clinic(s), %s active staff membership(s)',
       (select count(*) from public.organizations), (select count(*) from public.clinics),
       (select count(*) from public.staff_memberships where status = 'active')))
)
select ord, check_name,
       case when info is not null then 'INFO' when offenders is null then 'PASS' else 'FAIL' end as status,
       coalesce(info, pg_catalog.array_to_string(offenders, ', ')) as detail
  from checks order by ord;
